APXF["za-malmesbury"] = {"lede": "The ward around Malmesbury, the Swartland's main town, among wheatfields on Malmesbury shale.", "facts": [["Category", "WO"], ["Recognized", ""], ["Main grapes", "Pinotage, Shiraz, Chenin Blanc"]], "sections": [["The place", "<p>Its old dryland bush vines of Chenin Blanc and Pinotage were long sold to the Swartland Winery co-operative and are now sought by smaller producers too.</p>"], ["The rules", "<p>A Wine of Origin production area. South Africa's Wine of Origin scheme came into force in 1973 and now operates under the Liquor Products Act of 1989, administered by the Wine and Spirit Board. The law defines a hierarchy of geographical units (such as Western Cape), regions, districts and wards, plus registered single vineyards; overarching units such as Cape Coast and Greater Cape allow blends across regions. A ward must have a clear influence of soil, climate and ecology on the wine, and its name must reflect a real geographic feature. 'Wine of Origin' with an area name guarantees that 100% of the grapes come from that area; a variety or vintage on the label requires 85%. The certification seal on the bottle confirms that the claims were checked and the wine passed tasting. The scheme sets no rules on grapes, yields or style. This is a ward, the smallest level below a single vineyard.</p>"], ["In the glass", "<p>Old-vine Chenin Blanc and white blends; Syrah, Grenache, Cinsault and Rhône blends, unforced and fresh.</p>"], ["For the exam", "<p>Ward in the Swartland district, Coastal Region region.</p>"]], "producers": ["Swartland Winery"], "sources": [["Wines of South Africa: Wine of Origin scheme", "https://www.wosa.co.za/The-Industry/Wines-Of-Origin/Wine-Of-Origin-scheme"], ["Wine Certification Authority: What we do", "https://wineauthority.org/what-we-do"], ["SAWIS: Wine of Origin Scheme (Liquor Products Act 60 of 1989), updated 2025", "https://www.sawis.co.za/winelaw/download/Wine_of_Origin_Scheme,_updated_05_2025.pdf"]], "checked": "2026-11-14"};
